exercise.solution:
def split_shipment(weights, limit):
    light, heavy = [], []
    for w in weights:
        if w < limit:            # strictly light goes left
            light.append(w)
        else:                    # boundary and above go right
            heavy.append(w)
    return (light, heavy)

